<?php
$profit=$totalIncome-$totalExpense;
$monthProfit=$monthIncome-$monthExpense;
$monthNames=[1=>'Jan',2=>'Shk',3=>'Mar',4=>'Pri',5=>'Maj',6=>'Qer',7=>'Kor',8=>'Gus',9=>'Sht',10=>'Tet',11=>'Nën',12=>'Dhj'];
$chartMonths=[];
$chartStart=new DateTimeImmutable(date('Y-m-01'));
for($i=5;$i>=0;$i--){$month=$chartStart->modify('-'.$i.' months');$key=$month->format('Y-m');$chartMonths[$key]=['label'=>$monthNames[(int)$month->format('n')],'income'=>0.0,'expense'=>0.0,'profit'=>0.0];}
foreach($data['services'] as $service){$key=substr((string)$service['date'],0,7);if(isset($chartMonths[$key])){$chartMonths[$key]['income']+=(float)($service['cost']??0);$chartMonths[$key]['expense']+=(float)($service['expense']??0);}}
foreach($chartMonths as &$monthData)$monthData['profit']=$monthData['income']-$monthData['expense'];unset($monthData);
$chartValues=[];foreach($chartMonths as $monthData)$chartValues=array_merge($chartValues,[$monthData['income'],$monthData['expense'],$monthData['profit']]);
$chartMax=max(0,...$chartValues);$chartMin=min(0,...$chartValues);$chartRange=max(1,$chartMax-$chartMin);$plotTop=22;$plotBottom=218;$plotHeight=$plotBottom-$plotTop;$zeroY=$plotTop+($chartMax/$chartRange)*$plotHeight;
?>
<div class="page-heading"><div><span class="eyebrow">FINANCAT E SERVISIT</span><h1>Të hyrat dhe shpenzimet</h1><p>Krahaso të hyrat, kostot dhe fitimin e regjistruar në serviset e fundit.</p></div></div>
<section class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Të hyra këtë muaj</span><span class="stat-icon green">€</span></div><strong>€<?=number_format($monthIncome,2)?></strong><small>Vlera e faturuar e serviseve</small></article><article class="stat-card"><div class="stat-top"><span>Shpenzime këtë muaj</span><span class="stat-icon amber">€</span></div><strong>€<?=number_format($monthExpense,2)?></strong><small>Pjesë dhe materiale</small></article><article class="stat-card"><div class="stat-top"><span>Fitim i llogaritur këtë muaj</span><span class="stat-icon blue">↗</span></div><strong>€<?=number_format($monthProfit,2)?></strong><small>Të hyra minus shpenzime</small></article><article class="stat-card"><div class="stat-top"><span>Fitim i llogaritur gjithsej</span><span class="stat-icon violet">∑</span></div><strong>€<?=number_format($profit,2)?></strong><small>Që nga fillimi i të dhënave</small></article></section>

<section class="panel finance-chart-panel"><div class="panel-head finance-chart-head"><div><span class="eyebrow">TRENDET FINANCIARE</span><h2>Të hyra, shpenzime dhe fitim</h2><p>Krahasimi mujor për gjashtë muajt e fundit</p></div><span class="finance-chart-period">6 muaj</span></div>
  <div class="finance-legend"><span><i class="legend-income"></i>Të hyra</span><span><i class="legend-expense"></i>Shpenzime</span><span><i class="legend-profit"></i>Fitim</span></div>
  <div class="finance-chart-scroll"><svg class="finance-chart" viewBox="0 0 900 258" role="img" aria-labelledby="financeChartTitle financeChartDescription" preserveAspectRatio="xMinYMin meet"><title id="financeChartTitle">Krahasimi i të hyrave, shpenzimeve dhe fitimit</title><desc id="financeChartDescription">Diagram shtyllor mujor për gjashtë muajt e fundit. Fitimi llogaritet si të hyrat minus shpenzimet.</desc>
    <?php for($tick=0;$tick<=4;$tick++):$tickValue=$chartMax-($chartRange*$tick/4);$tickY=$plotTop+($plotHeight*$tick/4);?><line x1="70" y1="<?=$tickY?>" x2="890" y2="<?=$tickY?>" class="chart-grid-line"/><text x="60" y="<?=$tickY+4?>" class="chart-axis-label" text-anchor="end">€<?=number_format($tickValue,0)?></text><?php endfor;?>
    <line x1="70" y1="<?=$zeroY?>" x2="890" y2="<?=$zeroY?>" class="chart-zero-line"/>
    <?php $series=[['key'=>'income','color'=>'income'],['key'=>'expense','color'=>'expense'],['key'=>'profit','color'=>'profit']];$monthIndex=0;foreach($chartMonths as $monthKey=>$monthData):$center=70+($monthIndex*136)+68;foreach($series as $seriesIndex=>$item):$value=$monthData[$item['key']];$valueY=$plotTop+(($chartMax-$value)/$chartRange)*$plotHeight;$barY=min($zeroY,$valueY);$barHeight=max(1,abs($zeroY-$valueY));$x=$center-34+($seriesIndex*23);?><rect x="<?=$x?>" y="<?=$barY?>" width="17" height="<?=$barHeight?>" rx="4" class="chart-bar <?=$item['color']?>"><title><?=h($monthNames[(int)substr($monthKey,5,2)])?>: <?=h(['income'=>'Të hyra','expense'=>'Shpenzime','profit'=>'Fitim'][$item['key']])?> €<?=number_format($value,2)?></title></rect><?php endforeach;?><text x="<?=$center?>" y="250" class="chart-month-label" text-anchor="middle"><?=h($monthData['label'])?></text><?php $monthIndex++;endforeach;?>
  </svg></div><?php if(!$data['services']):?><p class="chart-empty-note">Diagrami do të plotësohet kur të regjistrohen serviset e para.</p><?php endif;?>
  <p class="chart-footnote">Fitimi = të hyrat e regjistruara − shpenzimet e regjistruara. Muajt pa servise shfaqen me vlerë €0.</p>
</section>

<section class="panel table-panel"><div class="panel-head"><div><h2>Pasqyra e ndërhyrjeve</h2><p>Shumat e regjistruara për secilën punë në servis</p></div></div><div class="table-wrap"><table><thead><tr><th>Data / vetura</th><th>Problemi / puna</th><th>Statusi</th><th>Të hyra</th><th>Shpenzime</th><th>Fitimi</th></tr></thead><tbody><?php foreach(array_reverse($data['services']) as $s):$exp=(float)($s['expense']??0);$income=(float)($s['cost']??0);?><tr><td><?=h(date('d.m.Y',strtotime($s['date'])))?><small class="table-sub"><?=h(vehicle_label($data,(int)$s['vehicle_id']))?></small></td><td><?=h($s['problem']??$s['type'])?><small class="table-sub"><?=h($s['type'])?></small></td><td><?=h(['pending'=>'Në pritje','in_progress'=>'Në proces','completed'=>'Përfunduar'][$s['status']??'completed']??'—')?></td><td class="amount">€<?=number_format($income,2)?></td><td>€<?=number_format($exp,2)?></td><td class="amount">€<?=number_format($income-$exp,2)?></td></tr><?php endforeach;?></tbody></table></div></section>
<p class="report-note">Shënim: të hyrat janë çmimet e faturuara; shpenzimet janë pjesët/materialet e regjistruara. Fitimi është llogaritje orientuese dhe nuk përfshin tatime apo paga.</p>
